CREATE TABLE habilidades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    codigo TEXT UNIQUE,
    etapa TEXT,
    ano INTEGER,
    componente TEXT,
    unidade_tematica TEXT,
    objeto_conhecimento TEXT,
    habilidade TEXT
);

